def count_independent_sets_recursive(adj, n):
    memo = {}
    def solve(idx, current_mask):
        if idx == n:
            return 1

        state = (idx, current_mask)
        if state in memo:
            return memo[state]

        # Option 1: Don't include vertex idx
        res = solve(idx + 1, current_mask)

        # Option 2: Include vertex idx (if possible)
        can_include = True
        for neighbor in adj[idx]:
            if neighbor < idx and (current_mask & (1 << neighbor)):
                can_include = False
                break

        if can_include:
            res += solve(idx + 1, current_mask | (1 << idx))

        memo[state] = res
        return res

