    dp[1, 0] = 1
    dp[1, 1] = 1
    dp[1, 2] = 1
    for i in range(2, n_grid + 1):
        dp[i, 0] = dp[i-1, 0] + dp[i-1, 1] + dp[i-1, 2]
        dp[i, 1] = dp[i-1, 0] + dp[i-1, 2]
        dp[i, 2] = dp[i-1, 0] + dp[i-1, 1]
    total_sets = dp[n_grid, 0] + dp[n_grid, 1] + dp[n_grid, 2]
